    bio: "187cm/95kg. 우투우타.\n1988년 08월 28일 출생.\n학력: 문촌초(일산리틀)-장성중-경기고-두산-상무-두산.\n프로 입단: 07 두산 2차 4라운드 26순위.\n소속: 두산 베어스 (2007~2024)[1] / LG 트윈스 (2025~).\n포지션: 중간 계투.",
