    tmi: "💡 TMI:\n• 등장곡: Fort Minor - 〈Remember the Name〉\n• 연봉: 2026 / 2억 2,000만원 57.1%↑\n• 등번호: 63번\n• 학력: 동막초-상인천중-인천고\n• , 신인상 최다 득표수 등의 기록을 경신한 선수이다.\n• 간혹 최준호 대신 같은 팀 선배 포수인 윤준호와 엮어서 부르기도 한다. 다만 메이저한 건 역시 최준호와의 조합. 이 별명으로 공중파 뉴스까지 탔다. 이후 당사자인 2PM 택연이 자신의 인스타 스토리를 통해 김택연을 응원했으며, 김택연 또한 자신의 인스타 스토리를 통해 이에 화답했다.",
