    tmi: "💡 TMI:\n• 등장곡: 코리아나 - 〈손에 손 잡고〉 (2024~)\n• 연봉: 2025 / 4억 원 FA\n• 등번호: 38번\n• 병역: 공익근무요원 (2005~2006)\n• 학력: 화곡초-성남중-성남고-두산-롯데\n• 을 차지하는 등 나이를 잊은 대활약을 보이고 있다.\n• 이러한 호성적을 바탕으로 2026 월드 베이스볼 클래식의 대표팀 최종 명단에 포함되면서 2013 월드 베이스볼 클래식 이후 13년 만에 태극마크를 달게 되었다.\n• 140km/h 초중반으로 구속이 떨어지며 구위도 하락하였다. 구위 하락 외에 지적받는 다른 문제점은 멘탈. 경기 내외적으로 자주 흔들리고 본인도 그에 휩쓸리는 모습을 자주 보여준다. 옆에서 믿어주며 바로 잡아주는 사람",
