  "원종현": {
    bio: "182cm/88kg. 우투우타.\n1987년 07월 31일 출생.\n학력: 군산중앙초-군산중-군산상고-LG-경찰-NC.\n프로 입단: 06 LG 2차 2라운드 11순위.\n소속: LG 트윈스 (2006~2010) / NC 다이노스 (2012~2022) / 키움 히어로즈 (2023~).\n포지션: 중간 계투 → 마무리 투수 → 중간 계투.",
    career: "🏆 주요 기록:\n• WBC 국가대표\n• WBSC 프리미어12 국가대표\n• 입단: 06 LG 2차 2라운드 11순위\n• --- KBO TOP10 기록 ---\n• 2022 경기 68 (6위)\n• 2017 경기 68 (7위)\n• 2014 경기 73 (2위)\n• 2021 세이브 14 (10위)\n• 2020 세이브 30 (2위)\n• 2019 세이브 31 (3위)\n• 2018 홀드 17 (4위)\n• 2017 홀드 22 (2위)\n• 2016 홀드 17 (4위)",
    tmi: "💡 TMI:\n• 등장곡: Blade & Soul OST - 〈Heed the call〉\n• 연봉: 2025 / 5억 원 FA\n• 등번호: 46번\n• 병역: 경찰 야구단\n• 학력: 군산중앙초-군산중-군산상고-LG-경찰-NC\n• 최고 구속 155km/h, 평균 148km/h 대의 묵직한 포심 패스트볼을 던지며 종 변화가 좋은 슬라이더를 장착하고 있다. 쓰리피치로는 포크볼을 구사한다. 상대를 압도할 수 있는 구위에 좋은 제구력까지 갖추며 K/9가 9를 넘어가는 탈삼진율을 보이고 있으며, 패스트볼과 슬라이더가 주무기인 스리쿼터 투수는 우타자의 천적임에도 좌타자를 훨씬 잘 잡아낸다.\n• 구위를 인정받은 패스트볼에 비해 2014년까지만 해도 슬라이더의 평은 그다지 좋지 않았다. 하지만 2015년 이후 복귀 준비를 하면서 박명환 당시 2군 코치에게 도움을 받아 더욱 날카롭게 다듬었다. 옆으로 휘는 것보다 종 변화에 더욱 중점을 두었고 그 결과 2014년 -1.6에 불과했던 슬라이더의 구종 가치가 2016년 5.3까지 상승했다. 2017년에는\n• 알다시피 원종현은 대장암 때문에 2015년을 통째로 쉬었다. 그럼에도 저렇게 많은 이닝을 기록한 것. 그럼에도 불구하고 2020년 지금도 아직까지 평균구속 147km/h 대의 빠른 공을 뿌리며 마무리투수로 활약하고 있다.",
  },
