    tmi: "💡 TMI:\n• 등장곡: G-DRAGON - 〈미치GO〉 (2025~)\n• 연봉: 2026 / 2억 원 170.3%↑\n• 등번호: 92번\n• 학력: 본리초-경복중-대구고\n• 여기서 파생되어 꽃돼지로도 불리고 있다. 하술할 토코몬과 함께 최지훈이 본인 응원가로 꽃돼지 안타~ 토코몬 안타~라고 쐐기박을 정도.\n• 학생수 부족으로 같은 재단인 경복중학교와 협성중학교가 폐합되었다. 그래서 졸업은 협성경복중학교에서 졸업을 했다.\n• 같은 해에 2라운드로 입단한 송영진과 발 사이즈가 같다.",
