    tmi: "💡 TMI:\n• 등장곡: 젝스키스 - 〈사나이 가는 길 (폼생폼사)〉\n• 연봉: 2026 / 1억 8,000만 원 50%↑\n• 등번호: 65번\n• 병역: 대한민국 육군 제8군단 병장 만기전역\n• 학력: 역북초-송전중-안산공고-두산\n• 을 달성하며 2022년 KBO 신인상을 수상했다. 그러나 이후 혹사로 인한 후유증을 겪으며 부진하다 2025 시즌을 앞두고 트레이드를 통해 롯데 자이언츠로 이적했다.\n• 일단 2026년 1월 25일부터 진행되는 1군 스프링캠프 일정은 정상적으로 소화한다. #\n• 신인 시절에는 같은 팀 선배였던 오재일을 닮았다. 베어스포티비피셜 오재일 순한 맛. 다만 군 전역 후 살이 많이 빠지면서 예전과는 외모가 많이 변했다. 팀 대선배격인 심재학은 정철원의 외모가 박명환과 닮은 것 같다고 말하기도 했다.",
