    tmi: "💡 TMI:\n• 연봉: 2026 / 6,700만 원 76.3%↑\n• 등번호: 20번\n• 병역: 대한민국 육군 제3군수지원여단 병장 만기 전역\n• 학력: 대전신흥초-충남중-백송고\n• 의 포심 구속으로 우완 선발 평균을 살짝 웃도는 구속을 가지고 있었다. 아직 젊은 투수고 고등학교 때에도 151을 던진 만큼 구속 향상의 여지는 충분하다. 속구와 더불어 슬라이더, 커브, 포크를 구사하며 속구의 비중이 약 60% 정도로 높은 편이다. 커브는 보여주기 식이 강하고, 기본적으로는 속구-슬라이더 조합의 투피치 투구에 상황에 따라 포크의 비중을 조\n• 선발과 롱릴리프, 추격조, 셋업맨, 마무리를 한 시즌에 다 뛸 정도로 활용도는 다양하나, 길게 던지는 것보단 짧게 전력투구 시의 성적이 더 뛰어나다.",
