    tmi: "💡 TMI:\n• 등장곡: Daddy Yankee - 〈Donante De Sangre〉\n• 연봉: 2026 / $900,000\n• 등번호: 46번\n• 학력: 베네수엘라 U.E.N heroes nigales(고)\n• Yonny Enrique Chirinos Mejias\n• 가 나오는 싱커로, 치리노스의 레퍼토리의 40~50%를 차지하며 이를 바탕으로 땅볼 유도가 비교적 많은 편이다. 홈 플레이트 앞에서 가라앉는 움직임이 좋아 땅볼뿐만 아니라 삼진 유도에도 나름 좋은 구종. 싱커와 함께 평균구속 85mph의 스플리터를 구사하는데, 싱커와 비슷하지만 다른 움직임을 바탕으로 치리노스의 또 하나의 주무기로 군림했다. 2019년 당시\n• 이후 미국의 베네수엘라 침공에도 다행히 농장이 수도와 상당히 멀리 떨어져있는지라 본인과 농장을 포함한 모든 것이 피해를 입지 않았으며 나중에 한국 목장을 방문해보고 싶다고 말했다. 그후 2026년에 송아지 17마리가 더 생겼다 밝혀, 최소 4~50마리 이상의 소가 있는것으로 확인된다.#",
